const incoming = $json.body ?? $json;
const headers = $json.headers ?? {};

const requestId = incoming.request_id || incoming.id || `req_${Date.now()}`;
const router = incoming.router || {
  route: incoming.route || incoming.semantic_route || 'pocket_ai',
  intent: incoming.intent || incoming.task || 'auto',
  confidence: incoming.route_confidence || incoming.confidence || null
};

const userText = incoming.text || incoming.user_message || incoming.query || incoming.prompt || incoming.command || '';
const context = incoming.context || {};
const media = incoming.media || {
  image_source: incoming.image_source || incoming.image_url || incoming.image_path || null,
  camera_id: incoming.camera_id || incoming.device || null,
  stream_id: incoming.stream_id || null
};

const tools = [
  {
    name: 'camera_stream.start_camera_stream',
    description: 'Start a local camera/video stream from Pocket AI.',
    parameters: {
      type: 'object',
      properties: {
        camera_id: { type: 'string' },
        resolution: { type: 'string', default: '640x480' },
        fps: { type: 'integer', default: 15 }
      },
      required: ['camera_id']
    }
  },
  {
    name: 'camera_stream.stop_camera_stream',
    description: 'Stop an active camera stream.',
    parameters: {
      type: 'object',
      properties: { stream_id: { type: 'string' } },
      required: ['stream_id']
    }
  },
  {
    name: 'object_detection.detect_objects',
    description: 'Detect objects in an image, URL, camera frame, or stream frame.',
    parameters: {
      type: 'object',
      properties: {
        image_source: { type: 'string' },
        model: { type: 'string', default: 'yolov8n' },
        confidence_threshold: { type: 'number', default: 0.35 },
        save_annotated: { type: 'boolean', default: true }
      },
      required: ['image_source']
    }
  },
  {
    name: 'object_detection.start_realtime_detection',
    description: 'Start realtime object detection over a stream.',
    parameters: {
      type: 'object',
      properties: {
        stream_id: { type: 'string' },
        model: { type: 'string', default: 'yolov8n' },
        confidence_threshold: { type: 'number', default: 0.35 },
        fps_limit: { type: 'integer', default: 5 }
      },
      required: ['stream_id']
    }
  },
  {
    name: 'object_detection.stop_realtime_detection',
    description: 'Stop a realtime object detection job.',
    parameters: {
      type: 'object',
      properties: { job_id: { type: 'string' } },
      required: ['job_id']
    }
  },
  {
    name: 'system_status.get_status',
    description: 'Return status of Pocket AI services.',
    parameters: {
      type: 'object',
      properties: { scope: { type: 'string', enum: ['all', 'camera', 'detection', 'storage'], default: 'all' } },
      required: []
    }
  },
  {
    name: 'file_storage.save_result',
    description: 'Save a result to local disk or MinIO/S3-compatible storage.',
    parameters: {
      type: 'object',
      properties: {
        filename: { type: 'string' },
        bucket: { type: 'string', default: 'pocket-ai' },
        payload: { type: 'object' }
      },
      required: ['filename', 'payload']
    }
  }
];

const prompt = {
  role: 'system',
  content: [
    'You are Function Gemma 270M running locally for strict tool calling only.',
    'Return only one compact JSON object with keys: tool_name, arguments, confidence, reason.',
    'Never answer conversationally. Never invent tools. Select exactly one whitelisted tool.',
    'If data is missing, choose system_status.get_status only when the user asks for status; otherwise choose the safest matching tool with explicit arguments from the input.'
  ].join(' ')
};

return [{
  json: {
    request_id: requestId,
    stage: 'post_routing_normalized',
    router,
    input: { text: userText, media, context, headers },
    function_gemma_request: {
      request_id: requestId,
      model: 'google/functiongemma-270m-it',
      temperature: 0,
      max_new_tokens: 256,
      mode: 'single_tool_call',
      system: prompt.content,
      user: {
        text: userText,
        router,
        media,
        context
      },
      tools,
      strict_output_schema: {
        type: 'object',
        required: ['tool_name', 'arguments'],
        properties: {
          tool_name: { type: 'string' },
          arguments: { type: 'object' },
          confidence: { type: 'number' },
          reason: { type: 'string' }
        }
      }
    }
  }
}];

const response = $json;
const toolCall = response.tool_call || response;
const allowed = new Set([
  'camera_stream.start_camera_stream',
  'camera_stream.stop_camera_stream',
  'object_detection.detect_objects',
  'object_detection.start_realtime_detection',
  'object_detection.stop_realtime_detection',
  'system_status.get_status',
  'file_storage.save_result'
]);

const toolName = toolCall.tool_name;
if (!toolName || !allowed.has(toolName)) {
  throw new Error(`Function Gemma returned a non-whitelisted tool: ${toolName}`);
}

const args = toolCall.arguments || {};
if (typeof args !== 'object' || Array.isArray(args)) {
  throw new Error('Function Gemma arguments must be a JSON object.');
}

return [{
  json: {
    request_id: response.request_id || toolCall.request_id || `req_${Date.now()}`,
    stage: 'tool_call_validated',
    model: response.model || 'google/functiongemma-270m-it',
    tool_call: {
      tool_name: toolName,
      arguments: args,
      confidence: Number(toolCall.confidence ?? 0),
      reason: toolCall.reason || ''
    },
    executor_request: {
      request_id: response.request_id || toolCall.request_id || `req_${Date.now()}`,
      tool_name: toolName,
      arguments: args
    }
  }
}];

const exec = $json;
return [{
  json: {
    ok: exec.ok === undefined ? true : exec.ok,
    request_id: exec.request_id,
    workflow: 'post-routing-functiongemma-pocket-ai',
    policy: 'tool_calling_model_local_only_google_functiongemma_270m_it',
    executed_tool: exec.tool_name || exec.tool_call?.tool_name,
    result: exec.result || exec.data || exec,
    error: exec.error || null,
    timestamp: new Date().toISOString()
  }
}];
